<?php require_once 'functions.php'; if(user()) redirect('index.php'); $title='Register';$error='';$nama='';$email='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$nama=trim($_POST['nama']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$confirm=$_POST['password_confirmation']??'';if(strlen($nama)<3||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<6||$pass!==$confirm)$error='Periksa nama, email, password minimal 6 karakter, dan konfirmasi password.';else{$s=$koneksi->prepare('SELECT id_user FROM users WHERE email=?');$s->bind_param('s',$email);$s->execute();if($s->get_result()->num_rows)$error='Email sudah terdaftar.';else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$koneksi->prepare("INSERT INTO users(nama,email,password,role) VALUES(?,?,?,'user')");$s->bind_param('sss',$nama,$email,$hash);$s->execute();flash('success','Registrasi berhasil. Silakan login.');redirect('login.php');}}}include 'header.php'; ?>
<div class="auth"><div class="panel"><span class="pill">AKUN BARU</span><h1>Buat Akun</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Nama Lengkap</label><input name="nama" value="<?=e($nama)?>" required><label>Email</label><input type="email" name="email" value="<?=e($email)?>" required><label>Password</label><input type="password" name="password" minlength="6" required><label>Konfirmasi Password</label><input type="password" name="password_confirmation" minlength="6" required><button class="btn full">Daftar</button></form><p>Sudah punya akun? <a href="login.php">Login</a></p></div></div><?php include 'footer.php'; ?>
